package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"strings"
	"syscall"
	"time"

	"github.com/bwmarrin/discordgo"
)

type config struct {
	token   string
	guildID string
}

func loadConfig(getenv func(string) string) (config, error) {
	cfg := config{
		token:   strings.TrimSpace(getenv("DISCORD_BOT_TOKEN")),
		guildID: strings.TrimSpace(getenv("DISCORD_GUILD_ID")),
	}
	if cfg.token == "" {
		return config{}, errors.New("DISCORD_BOT_TOKEN is required")
	}
	if strings.ContainsAny(cfg.token, " \t\r\n") {
		return config{}, errors.New("DISCORD_BOT_TOKEN must contain only the token, without a Bot prefix")
	}
	guildID, err := strconv.ParseUint(cfg.guildID, 10, 64)
	if err != nil || guildID == 0 {
		return config{}, errors.New("DISCORD_GUILD_ID must be a nonzero numeric server ID")
	}
	for _, character := range cfg.guildID {
		if character < '0' || character > '9' {
			return config{}, errors.New("DISCORD_GUILD_ID must be a nonzero numeric server ID")
		}
	}
	return cfg, nil
}

func main() {
	logger := slog.New(slog.NewJSONHandler(os.Stdout, nil))
	cfg, err := loadConfig(os.Getenv)
	if err != nil {
		logger.Error("invalid bot configuration", "error", err)
		os.Exit(1)
	}
	discordgo.Logger = func(level, _ int, _ string, _ ...interface{}) {
		// SDK diagnostics can include interaction tokens and authorization payloads.
		switch level {
		case discordgo.LogError:
			logger.Error("discord SDK reported a connection issue")
		case discordgo.LogWarning:
			logger.Warn("discord SDK reported a connection warning")
		}
	}
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	err = run(ctx, cfg, logger)
	stop()
	if err != nil {
		logger.Error("bot stopped", "error", err)
		os.Exit(1)
	}
}

func run(ctx context.Context, cfg config, logger *slog.Logger) error {
	session, err := discordgo.New("Bot " + cfg.token)
	if err != nil {
		return fmt.Errorf("create discord session: %w", safeDiscordError(err))
	}
	session.Identify.Intents = discordgo.IntentsGuilds
	session.StateEnabled = false
	session.SyncEvents = true
	session.LogLevel = discordgo.LogWarning
	session.Client = &http.Client{Timeout: 10 * time.Second}
	session.Dialer.HandshakeTimeout = 10 * time.Second

	startupCtx, cancel := context.WithTimeout(ctx, 30*time.Second)
	defer cancel()
	user, err := session.User("@me", discordgo.WithContext(startupCtx))
	if err != nil {
		return fmt.Errorf("authenticate bot: %w", safeDiscordError(err))
	}
	if user == nil || user.ID == "" {
		return errors.New("discord returned no bot identity")
	}
	if err := registerCommands(startupCtx, session, user.ID, cfg.guildID); err != nil {
		return err
	}
	cancel()
	session.AddHandler(func(s *discordgo.Session, event *discordgo.InteractionCreate) {
		if err := respond(ctx, s, event, cfg.guildID); err != nil && ctx.Err() == nil {
			logger.Error("slash command response failed", "error", err)
		}
	})
	session.AddHandler(func(_ *discordgo.Session, _ *discordgo.Ready) {
		logger.Info("bot connected", "guild_id", cfg.guildID)
	})
	if ctx.Err() != nil {
		return nil
	}
	if err := session.Open(); err != nil {
		return fmt.Errorf("connect discord gateway: %w", safeDiscordError(err))
	}
	defer func() {
		if err := session.Close(); err != nil {
			logger.Warn("close discord gateway", "error", safeDiscordError(err))
		}
	}()
	logger.Info("bot ready", "commands", "/ping, /about")
	<-ctx.Done()
	logger.Info("stopping bot")
	return nil
}

func registerCommands(ctx context.Context, session *discordgo.Session, appID, guildID string) error {
	commands := []*discordgo.ApplicationCommand{
		{Name: "ping", Description: "Check that the bot is responding.", Type: discordgo.ChatApplicationCommand},
		{Name: "about", Description: "Learn about this bot.", Type: discordgo.ChatApplicationCommand},
	}
	for _, command := range commands {
		_, err := session.ApplicationCommandCreate(appID, guildID, command, discordgo.WithContext(ctx))
		if err != nil {
			return fmt.Errorf("register /%s: %w", command.Name, safeDiscordError(err))
		}
	}
	return nil
}

func respond(
	ctx context.Context,
	session *discordgo.Session,
	event *discordgo.InteractionCreate,
	guildID string,
) error {
	if event == nil || event.Interaction == nil {
		return nil
	}
	if event.Type != discordgo.InteractionApplicationCommand || event.GuildID != guildID {
		return nil
	}
	data, ok := event.Data.(discordgo.ApplicationCommandInteractionData)
	if !ok {
		return nil
	}
	var content string
	switch data.Name {
	case "ping":
		content = "Pong! Your bot is online."
	case "about":
		content = "A Go slash-command bot built with DiscordGo. Make it your own: https://github.com/Deplexo/examples"
	default:
		return nil
	}
	responseCtx, cancel := context.WithTimeout(ctx, 2500*time.Millisecond)
	defer cancel()
	err := session.InteractionRespond(event.Interaction, &discordgo.InteractionResponse{
		Type: discordgo.InteractionResponseChannelMessageWithSource,
		Data: &discordgo.InteractionResponseData{
			Content: content,
			Flags:   discordgo.MessageFlagsEphemeral,
			AllowedMentions: &discordgo.MessageAllowedMentions{
				Parse: []discordgo.AllowedMentionType{},
			},
		},
	}, discordgo.WithContext(responseCtx), discordgo.WithRetryOnRatelimit(false))
	if err != nil {
		return fmt.Errorf("respond to /%s: %w", data.Name, safeDiscordError(err))
	}
	return nil
}

func safeDiscordError(err error) error {
	if errors.Is(err, context.Canceled) {
		return context.Canceled
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return context.DeadlineExceeded
	}
	if errors.Is(err, discordgo.ErrUnauthorized) {
		return errors.New("discord rejected the bot token; check DISCORD_BOT_TOKEN")
	}
	var restErr *discordgo.RESTError
	if errors.As(err, &restErr) && restErr.Response != nil {
		code := 0
		if restErr.Message != nil {
			code = restErr.Message.Code
		}
		return fmt.Errorf(
			"discord API returned HTTP %d (code %d); check the token, guild ID, and bot permissions",
			restErr.Response.StatusCode,
			code,
		)
	}
	var networkErr net.Error
	if errors.As(err, &networkErr) && networkErr.Timeout() {
		return errors.New("discord connection timed out")
	}
	return errors.New("discord connection failed; check credentials, server permissions, and connectivity")
}

package main

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"net/url"
	"strings"
	"testing"
	"time"

	"github.com/bwmarrin/discordgo"
)

type roundTripFunc func(*http.Request) (*http.Response, error)

func (fn roundTripFunc) RoundTrip(request *http.Request) (*http.Response, error) {
	return fn(request)
}

func testSession(t *testing.T, transport roundTripFunc) *discordgo.Session {
	t.Helper()
	session, err := discordgo.New("Bot example-test-token")
	if err != nil {
		t.Fatal(err)
	}
	session.Client = &http.Client{Transport: transport, Timeout: time.Second}
	session.MaxRestRetries = 0
	session.ShouldRetryOnRateLimit = false
	return session
}

func TestLoadConfig(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name    string
		token   string
		guildID string
		wantErr bool
	}{
		{name: "valid", token: "test-token", guildID: "123456789012345678"},
		{name: "trimmed", token: " test-token\n", guildID: " 123456789012345678 "},
		{name: "missing token", guildID: "123", wantErr: true},
		{name: "missing guild", token: "test-token", wantErr: true},
		{name: "prefixed token", token: "Bot secret-token", guildID: "123", wantErr: true},
		{name: "invalid guild", token: "secret-token", guildID: "abc", wantErr: true},
		{name: "zero guild", token: "secret-token", guildID: "0", wantErr: true},
		{name: "signed guild", token: "secret-token", guildID: "+123", wantErr: true},
		{name: "overflow guild", token: "secret-token", guildID: "18446744073709551616", wantErr: true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			values := map[string]string{"DISCORD_BOT_TOKEN": tt.token, "DISCORD_GUILD_ID": tt.guildID}
			cfg, err := loadConfig(func(key string) string { return values[key] })
			if (err != nil) != tt.wantErr {
				t.Fatalf("loadConfig error = %v, want error %v", err, tt.wantErr)
			}
			if err != nil {
				if strings.Contains(err.Error(), "secret-token") {
					t.Fatal("configuration error exposed token")
				}
				return
			}
			if cfg.token != strings.TrimSpace(tt.token) || cfg.guildID != strings.TrimSpace(tt.guildID) {
				t.Fatal("configuration did not normalize surrounding whitespace")
			}
		})
	}
}

func TestRegisterCommandsPreservesOtherCommands(t *testing.T) {
	t.Parallel()
	names := []string{}
	session := testSession(t, func(request *http.Request) (*http.Response, error) {
		if request.Method != http.MethodPost {
			t.Fatalf("method = %s; only individual command upserts are allowed", request.Method)
		}
		if !strings.HasSuffix(request.URL.Path, "/applications/app-id/guilds/guild-id/commands") {
			t.Fatalf("unexpected command endpoint: %s", request.URL.Path)
		}
		if request.Context().Value(testContextKey{}) != "registration" {
			t.Fatal("registration lost caller context")
		}
		var command discordgo.ApplicationCommand
		if err := json.NewDecoder(request.Body).Decode(&command); err != nil {
			t.Fatal(err)
		}
		names = append(names, command.Name)
		if command.Type != discordgo.ChatApplicationCommand || command.Description == "" {
			t.Fatal("command lacks slash-command type or description")
		}
		return &http.Response{
			StatusCode: http.StatusOK,
			Header:     http.Header{},
			Body:       io.NopCloser(strings.NewReader(`{"id":"command-id"}`)),
		}, nil
	})
	ctx := context.WithValue(t.Context(), testContextKey{}, "registration")
	for range 2 {
		if err := registerCommands(ctx, session, "app-id", "guild-id"); err != nil {
			t.Fatal(err)
		}
	}
	if strings.Join(names, ",") != "ping,about,ping,about" {
		t.Fatalf("registered commands = %v", names)
	}
}

type testContextKey struct{}

func TestRespondToSlashCommands(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name    string
		content string
	}{
		{name: "ping", content: "Pong! Your bot is online."},
		{name: "about", content: "DiscordGo"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			calls := 0
			session := testSession(t, func(request *http.Request) (*http.Response, error) {
				calls++
				if request.Method != http.MethodPost || !strings.HasSuffix(request.URL.Path, "/interactions/event-id/interaction-secret/callback") {
					t.Fatalf("unexpected interaction endpoint: %s %s", request.Method, request.URL.Path)
				}
				if deadline, ok := request.Context().Deadline(); !ok || time.Until(deadline) > 2500*time.Millisecond {
					t.Fatal("initial response has no bounded deadline")
				}
				var response discordgo.InteractionResponse
				if err := json.NewDecoder(request.Body).Decode(&response); err != nil {
					t.Fatal(err)
				}
				if response.Type != discordgo.InteractionResponseChannelMessageWithSource {
					t.Fatalf("response type = %d", response.Type)
				}
				if response.Data == nil || !strings.Contains(response.Data.Content, tt.content) {
					t.Fatalf("unexpected response data: %+v", response.Data)
				}
				if response.Data.Flags != discordgo.MessageFlagsEphemeral {
					t.Fatal("response is not ephemeral")
				}
				return &http.Response{
					StatusCode: http.StatusNoContent,
					Header:     http.Header{},
					Body:       io.NopCloser(strings.NewReader("")),
				}, nil
			})
			event := &discordgo.InteractionCreate{Interaction: &discordgo.Interaction{
				ID: "event-id", Token: "interaction-secret", GuildID: "guild-id",
				Type: discordgo.InteractionApplicationCommand,
				Data: discordgo.ApplicationCommandInteractionData{Name: tt.name},
			}}
			if err := respond(t.Context(), session, event, "guild-id"); err != nil {
				t.Fatal(err)
			}
			if calls != 1 {
				t.Fatalf("callback requests = %d, want 1", calls)
			}
		})
	}
}

func TestRespondIgnoresUnrelatedEvents(t *testing.T) {
	t.Parallel()
	session := testSession(t, func(*http.Request) (*http.Response, error) {
		t.Fatal("unrelated event sent an API request")
		return nil, errors.New("unexpected request")
	})
	tests := []struct {
		name  string
		event *discordgo.InteractionCreate
	}{
		{name: "nil"},
		{name: "empty", event: &discordgo.InteractionCreate{}},
		{name: "component", event: &discordgo.InteractionCreate{Interaction: &discordgo.Interaction{
			Type: discordgo.InteractionMessageComponent, GuildID: "guild-id",
		}}},
		{name: "another guild", event: &discordgo.InteractionCreate{Interaction: &discordgo.Interaction{
			Type: discordgo.InteractionApplicationCommand, GuildID: "different-guild",
			Data: discordgo.ApplicationCommandInteractionData{Name: "ping"},
		}}},
		{name: "unknown command", event: &discordgo.InteractionCreate{Interaction: &discordgo.Interaction{
			Type: discordgo.InteractionApplicationCommand, GuildID: "guild-id",
			Data: discordgo.ApplicationCommandInteractionData{Name: "other-command"},
		}}},
		{name: "missing data", event: &discordgo.InteractionCreate{Interaction: &discordgo.Interaction{
			Type: discordgo.InteractionApplicationCommand, GuildID: "guild-id",
		}}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if err := respond(t.Context(), session, tt.event, "guild-id"); err != nil {
				t.Fatal(err)
			}
		})
	}
}

func TestAPIFailuresNeverExposeSecrets(t *testing.T) {
	t.Parallel()
	session := testSession(t, func(request *http.Request) (*http.Response, error) {
		return &http.Response{
			StatusCode: http.StatusForbidden,
			Status:     "403 Forbidden",
			Header:     http.Header{},
			Body:       io.NopCloser(strings.NewReader(`{"code":50013,"message":"example-test-token interaction-secret"}`)),
			Request:    request,
		}, nil
	})
	registrationErr := registerCommands(t.Context(), session, "app-id", "guild-id")
	event := &discordgo.InteractionCreate{Interaction: &discordgo.Interaction{
		ID: "event-id", Token: "interaction-secret", GuildID: "guild-id",
		Type: discordgo.InteractionApplicationCommand,
		Data: discordgo.ApplicationCommandInteractionData{Name: "ping"},
	}}
	responseErr := respond(t.Context(), session, event, "guild-id")
	for _, err := range []error{registrationErr, responseErr} {
		if err == nil || !strings.Contains(err.Error(), "HTTP 403") || !strings.Contains(err.Error(), "50013") {
			t.Fatalf("expected useful sanitized API error, got %v", err)
		}
		if strings.Contains(err.Error(), "example-test-token") || strings.Contains(err.Error(), "interaction-secret") {
			t.Fatal("API error exposed a token")
		}
	}
}

func TestNetworkErrorsNeverExposeRequestURL(t *testing.T) {
	t.Parallel()
	err := safeDiscordError(&url.Error{
		Op:  "Post",
		URL: "https://discord.com/api/interactions/id/interaction-secret/callback",
		Err: errors.New("example-test-token"),
	})
	if strings.Contains(err.Error(), "interaction-secret") || strings.Contains(err.Error(), "example-test-token") {
		t.Fatal("network error exposed a token")
	}
	if !errors.Is(safeDiscordError(context.Canceled), context.Canceled) {
		t.Fatal("cancellation lost its identity")
	}
}

package main

import (
	"context"
	"encoding/json"
	"errors"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"strings"
	"syscall"
	"time"
)

func handler() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	})
	mux.HandleFunc("GET /", func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/" {
			http.NotFound(w, r)
			return
		}
		writeJSON(w, http.StatusOK, map[string]string{"message": "Hello from Deplexo", "health": "/healthz", "greeting": "/greet?name=Alex"})
	})
	mux.HandleFunc("GET /greet", func(w http.ResponseWriter, r *http.Request) {
		name := strings.TrimSpace(r.URL.Query().Get("name"))
		if len(name) == 0 || len(name) > 80 {
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "name must contain 1 to 80 bytes"})
			return
		}
		writeJSON(w, http.StatusOK, map[string]string{"message": "Hello, " + name + "!"})
	})
	return mux
}
func writeJSON(w http.ResponseWriter, status int, value any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.WriteHeader(status)
	if err := json.NewEncoder(w).Encode(value); err != nil {
		slog.Error("write response", "error", err)
	}
}
func run() error {
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}
	server := &http.Server{Addr: ":" + port, Handler: handler(), ReadHeaderTimeout: 5 * time.Second, ReadTimeout: 10 * time.Second, WriteTimeout: 10 * time.Second, IdleTimeout: 60 * time.Second}
	stopped := make(chan struct{})
	finish := context.AfterFunc(ctx, func() {
		defer close(stopped)
		shutdown, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		if err := server.Shutdown(shutdown); err != nil {
			slog.Error("shutdown server", "error", err)
			if err := server.Close(); err != nil {
				slog.Error("close server", "error", err)
			}
		}
	})
	defer finish()
	slog.Info("HTTP API listening", "port", port)
	if err := server.ListenAndServe(); !errors.Is(err, http.ErrServerClosed) {
		return err
	}
	<-stopped
	return nil
}
func main() {
	if err := run(); err != nil {
		slog.Error("server stopped", "error", err)
		os.Exit(1)
	}
}

package main

import (
	"encoding/json"
	"net/http/httptest"
	"testing"
)

func TestHTTP(t *testing.T) {
	for _, tc := range []struct {
		name, path string
		status     int
	}{{"health", "/healthz", 200}, {"greeting", "/greet?name=Alex", 200}, {"missing name", "/greet", 400}, {"unknown", "/missing", 404}} {
		t.Run(tc.name, func(t *testing.T) {
			w := httptest.NewRecorder()
			handler().ServeHTTP(w, httptest.NewRequest("GET", tc.path, nil))
			if w.Code != tc.status {
				t.Fatalf("status=%d want %d", w.Code, tc.status)
			}
			if tc.status == 200 {
				var body map[string]string
				if err := json.Unmarshal(w.Body.Bytes(), &body); err != nil {
					t.Fatal(err)
				}
			}
		})
	}
}

package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"regexp"
	"strings"
	"syscall"
	"time"

	"github.com/PaulSonOfLars/gotgbot/v2"
	"github.com/PaulSonOfLars/gotgbot/v2/ext"
	"github.com/PaulSonOfLars/gotgbot/v2/ext/handlers"
)

var tokenPattern = regexp.MustCompile(`^[1-9][0-9]*:[A-Za-z0-9_-]+$`)

func main() {
	if err := run(); err != nil {
		slog.Error("Bot stopped", "error", err)
		os.Exit(1)
	}
}

func run() error {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	token, err := validateToken(os.Getenv("TELEGRAM_BOT_TOKEN"))
	if err != nil {
		return err
	}
	bot, err := newBot(token, http.Client{Timeout: 30 * time.Second})
	if err != nil {
		return err
	}
	if ctx.Err() != nil {
		return nil
	}
	updater := ext.NewUpdater(newDispatcher(), &ext.UpdaterOpts{
		UnhandledErrFunc: func(err error) {
			if !errors.Is(err, context.Canceled) {
				slog.Warn("Telegram polling failed; retrying", "error", safeTelegramError(err))
			}
		},
	})
	if err := updater.StartPolling(bot, &ext.PollingOpts{
		EnableWebhookDeletion: true,
		GetUpdatesOpts: &gotgbot.GetUpdatesOpts{
			AllowedUpdates: []string{"message"},
			Timeout:        20,
			RequestOpts:    &gotgbot.RequestOpts{Timeout: 25 * time.Second},
		},
	}); err != nil {
		return fmt.Errorf("start polling: %w", safeTelegramError(err))
	}
	slog.Info("Bot ready", "username", bot.Username, "commands", "/start /help /ping")
	<-ctx.Done()
	if err := updater.Stop(); err != nil {
		return fmt.Errorf("stop polling: %w", safeTelegramError(err))
	}
	slog.Info("Bot stopped cleanly")
	return nil
}

func validateToken(raw string) (string, error) {
	token := strings.TrimSpace(raw)
	if token == "" {
		return "", errors.New("TELEGRAM_BOT_TOKEN is required; create a bot with @BotFather")
	}
	if !tokenPattern.MatchString(token) {
		return "", errors.New("TELEGRAM_BOT_TOKEN has an invalid format; copy the complete token from @BotFather")
	}
	return token, nil
}

func newBot(token string, client http.Client) (*gotgbot.Bot, error) {
	bot, err := gotgbot.NewBot(token, &gotgbot.BotOpts{
		BotClient: &gotgbot.BaseBotClient{
			Client:             client,
			DefaultRequestOpts: &gotgbot.RequestOpts{Timeout: 10 * time.Second},
		},
	})
	if err != nil {
		return nil, fmt.Errorf("connect to Telegram: %w", safeTelegramError(err))
	}
	return bot, nil
}

func newDispatcher() *ext.Dispatcher {
	dispatcher := ext.NewDispatcher(&ext.DispatcherOpts{
		MaxRoutines: 8,
		Error: func(_ *gotgbot.Bot, _ *ext.Context, err error) ext.DispatcherAction {
			slog.Error("Command failed", "error", safeTelegramError(err))
			return ext.DispatcherActionNoop
		},
		Panic: func(_ *gotgbot.Bot, _ *ext.Context, _ any) {
			slog.Error("Command panicked; check your handler implementation")
		},
		UnhandledErrFunc: func(err error) {
			slog.Error("Update failed", "error", safeTelegramError(err))
		},
	})
	dispatcher.AddHandler(handlers.NewCommand("start", reply("Hello! Your Go Telegram bot is running. Send /help to see the commands.")))
	dispatcher.AddHandler(handlers.NewCommand("help", reply("/start — Say hello\n/help — Show commands\n/ping — Check that the bot is online")))
	dispatcher.AddHandler(handlers.NewCommand("ping", reply("Pong!")))
	return dispatcher
}

func reply(text string) handlers.Response {
	return func(bot *gotgbot.Bot, ctx *ext.Context) error {
		if ctx.EffectiveMessage == nil {
			return nil
		}
		_, err := ctx.EffectiveMessage.ReplyMessage(bot, text, nil)
		if err != nil {
			return safeTelegramError(err)
		}
		return nil
	}
}

// Telegram errors can contain request URLs with the bot token or private message text.
func safeTelegramError(err error) error {
	var apiError *gotgbot.TelegramError
	if errors.As(err, &apiError) {
		switch apiError.Code {
		case http.StatusUnauthorized:
			return errors.New("Telegram rejected TELEGRAM_BOT_TOKEN; replace it with a valid @BotFather token")
		case http.StatusConflict:
			return errors.New("another bot instance is polling; run only one instance with this token")
		case http.StatusTooManyRequests:
			return errors.New("Telegram rate limit reached; reduce outgoing messages")
		default:
			return fmt.Errorf("Telegram API returned error code %d", apiError.Code)
		}
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return errors.New("Telegram request timed out; check outbound connectivity")
	}
	if errors.Is(err, context.Canceled) {
		return errors.New("Telegram request canceled")
	}
	return errors.New("Telegram request failed; check the bot token and outbound connectivity")
}

package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"testing"

	"github.com/PaulSonOfLars/gotgbot/v2"
)

func TestValidateToken(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name string
		raw  string
		want string
	}{
		{name: "missing"},
		{name: "blank", raw: " \n"},
		{name: "malformed", raw: "secret-that-must-not-be-logged"},
		{name: "invalid ID", raw: "zero:secret"},
		{name: "valid", raw: "12345:example_SECRET-123", want: "12345:example_SECRET-123"},
		{name: "surrounding whitespace", raw: " 12345:example_SECRET-123\n", want: "12345:example_SECRET-123"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			token, err := validateToken(tt.raw)
			if tt.want != "" {
				if err != nil || token != tt.want {
					t.Fatalf("valid token was not accepted: %v", err)
				}
				return
			}
			if err == nil || token != "" || !strings.Contains(err.Error(), "TELEGRAM_BOT_TOKEN") {
				t.Fatalf("invalid token must return actionable configuration error: %v", err)
			}
			if strings.TrimSpace(tt.raw) != "" && strings.Contains(err.Error(), tt.raw) {
				t.Fatal("error exposed the supplied token")
			}
		})
	}
}

func TestCommands(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name string
		text string
		want string
	}{
		{name: "start", text: "/start", want: "Your Go Telegram bot is running"},
		{name: "help", text: "/help", want: "/ping"},
		{name: "ping", text: "/ping", want: "Pong!"},
		{name: "addressed command", text: "/ping@example_bot", want: "Pong!"},
		{name: "other bot", text: "/ping@other_bot"},
		{name: "ordinary message", text: "hello"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			var replies int
			client := http.Client{Transport: roundTripFunc(func(req *http.Request) (*http.Response, error) {
				replies++
				defer req.Body.Close()
				if req.Method != http.MethodPost || !strings.HasSuffix(req.URL.Path, "/sendMessage") {
					t.Errorf("unexpected Telegram method: %s", req.Method)
				}
				if err := req.ParseMultipartForm(1 << 20); err != nil {
					t.Fatal(err)
				}
				defer req.MultipartForm.RemoveAll()
				if req.FormValue("chat_id") != "42" || !strings.Contains(req.FormValue("text"), tt.want) {
					t.Errorf("reply went to wrong chat or had unexpected text: %q", req.FormValue("text"))
				}
				return telegramResponse(`{"ok":true,"result":{"message_id":8,"chat":{"id":42,"type":"private"}}}`), nil
			})}
			bot := &gotgbot.Bot{
				Token:     "12345:test_token",
				User:      gotgbot.User{Id: 12345, Username: "example_bot", IsBot: true},
				BotClient: &gotgbot.BaseBotClient{Client: client},
			}
			update := &gotgbot.Update{Message: &gotgbot.Message{
				MessageId: 7,
				Text:      tt.text,
				From:      &gotgbot.User{Id: 42},
				Chat:      gotgbot.Chat{Id: 42, Type: "private"},
			}}
			if err := newDispatcher().ProcessUpdate(bot, update, nil); err != nil {
				t.Fatal(err)
			}
			wantReplies := 0
			if tt.want != "" {
				wantReplies = 1
			}
			if replies != wantReplies {
				t.Errorf("sent %d replies, want %d", replies, wantReplies)
			}
		})
	}
}

func TestNewBotRejectsUnauthorizedTokenWithoutExposingIt(t *testing.T) {
	t.Parallel()
	const token = "12345:private_test_token"
	client := http.Client{Transport: roundTripFunc(func(req *http.Request) (*http.Response, error) {
		defer req.Body.Close()
		if _, err := io.Copy(io.Discard, req.Body); err != nil {
			t.Fatal(err)
		}
		return telegramResponse(`{"ok":false,"error_code":401,"description":"` + token + `"}`), nil
	})}
	bot, err := newBot(token, client)
	if bot != nil || err == nil || !strings.Contains(err.Error(), "TELEGRAM_BOT_TOKEN") {
		t.Fatalf("expected actionable authentication failure, got %v", err)
	}
	if strings.Contains(err.Error(), token) {
		t.Fatal("authentication error exposed token")
	}
}

func TestSafeTelegramError(t *testing.T) {
	t.Parallel()
	const token = "12345:private_test_token"
	for _, tt := range []struct {
		name string
		err  error
	}{
		{name: "URL error", err: &url.Error{Op: "Post", URL: "https://api.telegram.org/bot" + token + "/getUpdates", Err: errors.New("offline")}},
		{name: "timeout", err: fmt.Errorf("request %s: %w", token, context.DeadlineExceeded)},
		{name: "another poller", err: &gotgbot.TelegramError{Code: 409, Description: token}},
		{name: "rate limit", err: &gotgbot.TelegramError{Code: 429, Description: token}},
		{name: "API failure", err: &gotgbot.TelegramError{Code: 500, Description: token}},
	} {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			message := safeTelegramError(tt.err).Error()
			if strings.Contains(message, token) || strings.Contains(message, "https://") {
				t.Fatal("error exposed sensitive request details")
			}
		})
	}
}

type roundTripFunc func(*http.Request) (*http.Response, error)

func (f roundTripFunc) RoundTrip(req *http.Request) (*http.Response, error) { return f(req) }

func telegramResponse(body string) *http.Response {
	return &http.Response{
		StatusCode: http.StatusOK,
		Header:     make(http.Header),
		Body:       io.NopCloser(strings.NewReader(body)),
	}
}

