import type { Metadata } from "next";
export const dynamic = "force-dynamic";
export const metadata: Metadata = { title: "Contact — Forma", description: "Start a conversation with the Forma team." };
export default function Contact() {
  const configured = process.env.CONTACT_EMAIL || "hello@example.com";
  const email = /^[^\s@?&#]+@[^\s@?&#]+\.[^\s@?&#]+$/.test(configured) ? configured : "hello@example.com";
  return <main className="contact-page container"><a className="brand" href="/">forma<span>.</span></a><div className="contact-card"><p className="eyebrow">A conversation starts here</p><h1>Tell us what<br />you’re working on.</h1><p>Good things start with a little context. Tell us about your team, your idea, and what you’d like to make possible.</p><a className="button button-primary" href={`mailto:${email}?subject=${encodeURIComponent("Let's talk about Forma")}`}>Write to {email} ↗</a><p className="contact-note">This opens your email application. This starter does not store messages or send email on your behalf.</p><a href="/">← Back to the website</a></div></main>;
}

:root { color-scheme: dark; --background: #13221b; --surface: #192920; --text: #eff1e8; --muted: #b0bbae; --subtle: #839681; --line: #344337; --lime: #d5e891; --ink: #1e2b20; }
* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 30px; }
body { margin: 0; background: var(--background); color: var(--text); font-family: Arial, Helvetica, sans-serif; -webkit-font-smoothing: antialiased; }
a { color: inherit; text-decoration: none; }
button, input, textarea { font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
a:focus-visible, summary:focus-visible, button:focus-visible, input:focus-visible, textarea:focus-visible { outline: 2px solid var(--lime); outline-offset: 6px; }
::selection { color: var(--ink); background: var(--lime); }
svg { display: inline-block; flex-shrink: 0; }
.container { width: min(1120px, calc(100% - 96px)); margin-inline: auto; }
.skip-link { position: absolute; z-index: 10; left: 16px; top: 12px; padding: 12px 18px; background: var(--lime); color: var(--ink); transform: translateY(-150%); border-radius: 5px; }
.skip-link:focus { transform: translateY(0); }
.site-header { display: flex; align-items: center; justify-content: space-between; gap: 28px; height: 108px; border-bottom: 1px solid var(--line); }
.brand { display: inline-flex; align-items: center; gap: 10px; font-size: 28px; font-weight: 600; letter-spacing: -.065em; }
.brand-mark { color: var(--lime); }
.site-header nav { display: flex; align-items: center; gap: 34px; font-size: 12px; color: var(--muted); margin-left: auto; margin-right: 25px; }
.site-header nav a:hover, .footer-bottom a:hover { color: var(--lime); }
.button { display: inline-flex; justify-content: center; align-items: center; gap: 27px; border-radius: 5px; padding: 18px 23px; font-size: 13px; font-weight: 500; border: 1px solid transparent; transition: background .18s, border-color .18s, transform .18s; }
.button svg { width: 17px; height: 17px; }
.button:hover { transform: translateY(-2px); }
.button-primary { background: var(--lime); color: var(--ink); }
.button-primary:hover { background: #e2f3ab; }
.button-small { padding: 11px 16px; gap: 20px; font-size: 11px; }
.button-outline { border-color: #56654d; background: transparent; }
.button-outline:hover { border-color: var(--lime); background: #d5e89108; }
.button-dark { background: var(--ink); color: var(--text); }
.button-dark:hover { background: #314332; }
.text-link { display: inline-flex; align-items: center; gap: 15px; font-size: 12px; line-height: 1.6; }
.text-link:hover { color: var(--lime); }
.eyebrow { display: inline-flex; align-items: center; gap: 10px; color: var(--muted); font: 9px/1.7 "Courier New", Courier, monospace; letter-spacing: .12em; }
.eyebrow > i { width: 5px; height: 5px; border-radius: 50%; background: var(--lime); box-shadow: 0 0 0 4px #d5e8910d; }
.hero { position: relative; display: grid; grid-template-columns: 1.3fr 1fr; align-items: center; gap: 30px; padding-top: 100px; padding-bottom: 106px; }
.hero h1 { margin: 25px 0 23px; font-size: clamp(60px, 6.75vw, 92px); font-weight: 400; line-height: .98; letter-spacing: -.075em; }
.hero h1 > span { color: var(--lime); }
.hero-copy > p { font-size: 15px; color: var(--muted); line-height: 1.8; margin: 0 0 33px; }
.hero-actions { display: flex; align-items: center; gap: 25px; flex-wrap: wrap; }
.hero-footnote { margin-top: 41px; display: flex; gap: 20px; color: var(--subtle); font: 8px/1.6 "Courier New", monospace; letter-spacing: .09em; }
.hero-footnote > span + span { border-left: 1px solid var(--line); padding-left: 20px; }
.hero-art { position: relative; aspect-ratio: 1; margin-top: 16px; overflow: clip; }
.art-guide { position: absolute; background: #5c70423d; }
.guide-horizontal { height: 1px; width: 100%; left: 0; top: 50%; }
.guide-vertical { width: 1px; height: 100%; top: 0; left: 50%; }
.art-coordinate { position: absolute; font: 6px/1.6 "Courier New", monospace; letter-spacing: .13em; color: #a6b890; }
.coordinate-top { left: 0; top: 0; }
.coordinate-bottom { bottom: 0; right: 0; }
.art-cross { position: absolute; color: #9bb27b; font: 13px/1 monospace; }
.cross-one { right: -3px; top: -5px; }
.cross-two { left: -3px; bottom: -5px; }
.orbital-sculpture { position: absolute; inset: 4%; transform: rotate(-20deg); }
.orbit { position: absolute; border: 1px solid #b6cd78; border-radius: 50%; inset: 2%; background: radial-gradient(ellipse at 50% 50%, transparent 55%, #d2e79005 80%); box-shadow: inset 2px 1px 0 #d2e79008, 1px 1px 0 #d2e79008; }
.orbit-one { transform: rotateY(55deg) rotateX(10deg); }
.orbit-two { transform: rotate(45deg) rotateY(55deg) rotateX(10deg); }
.orbit-three { transform: rotate(90deg) rotateY(55deg) rotateX(10deg); }
.orbit-four { transform: rotate(135deg) rotateY(55deg) rotateX(10deg); }
.orbital-sculpture > span { position: absolute; inset: 0; display: grid; place-items: center; font: italic 165px/1 Georgia, "Times New Roman", serif; padding-bottom: 25px; color: var(--lime); transform: rotate(20deg); }
.section-heading { display: flex; align-items: flex-end; justify-content: space-between; gap: 30px; margin-bottom: 35px; }
.section-heading h2, .approach-copy h2, .faq-section h2 { margin: 15px 0 0; font-size: 42px; font-weight: 400; line-height: 1.12; letter-spacing: -.055em; }
.section-heading > p { font-size: 12px; line-height: 1.8; color: var(--muted); margin: 0 0 4px; }
.product-section { padding-bottom: 90px; }
.product-heading h2 { font-size: 29px; }
.product-heading .eyebrow { font-size: 8px; }
.product-preview { display: grid; grid-template-columns: 190px minmax(0, 1fr); border: 1px solid #4a5a41; border-radius: 12px; overflow: hidden; background: #1d2a21; box-shadow: 0 35px 65px -25px #030c0880, 0 0 0 8px #43513121; }
.preview-sidebar { position: relative; display: flex; flex-direction: column; min-height: 457px; padding: 23px 14px 19px; background: #18251d; border-right: 1px solid #354330; }
.preview-brand { display: flex; gap: 7px; align-items: center; margin: 0 9px 23px; font-size: 19px; letter-spacing: -.05em; }
.preview-brand .brand-mark { width: 21px; height: 21px; }
.workspace-name { display: flex; align-items: center; gap: 7px; border: 1px solid #3c4935; border-radius: 4px; padding: 8px; font-size: 8px; }
.workspace-name > span:first-child { display: grid; place-items: center; height: 19px; width: 19px; background: #3e4c32; border-radius: 4px; font-size: 8px; }
.workspace-name > span:last-child { margin-left: auto; color: #a9b29e; }
.preview-menu { display: flex; flex-direction: column; gap: 3px; margin-top: 18px; }
.preview-menu > span { display: flex; align-items: center; gap: 9px; border-radius: 4px; padding: 9px; font-size: 13px; color: #a0ad98; }
.preview-menu > span > span { font-size: 9px; }
.preview-menu small { margin-left: auto; font: 7px/1 monospace; padding: 3px; border: 1px solid #3a4633; border-radius: 3px; }
.preview-menu .selected { color: #d6e6b4; background: #35442b; }
.preview-menu i { width: 4px; height: 4px; border-radius: 50%; background: #d5e891; margin-left: auto; }
