import { app } from './app.js';
const port=Number(process.env.PORT||3000);
if (!Number.isInteger(port)||port<1||port>65535) throw new Error('PORT must be a valid port number');
const server=app.listen(port,'0.0.0.0',()=>console.info(`HTTP API listening on ${port}`));
server.requestTimeout=15000;server.headersTimeout=10000;
let stopping=false;
function shutdown(){if(stopping)return;stopping=true;console.info('Shutting down');server.close(err=>{if(err){console.error('Failed to close server');process.exitCode=1;}});setTimeout(()=>server.closeAllConnections(),10000).unref();}
process.on('SIGTERM',shutdown);process.on('SIGINT',shutdown);

from fastapi import FastAPI
from pydantic import BaseModel, Field

app = FastAPI(title="Deplexo API starter", version="1.0.0")

class Greeting(BaseModel):
    name: str = Field(min_length=1, max_length=80, pattern=r".*\S.*")

@app.get("/healthz")
def health():
    return {"status": "ok"}

@app.get("/")
def index():
    return {"message": "Hello from Deplexo", "docs": "/docs"}

@app.post("/greet")
def greet(body: Greeting):
    return {"message": f"Hello, {body.name.strip()}!"}

from fastapi.testclient import TestClient
from app import app

client = TestClient(app)

def test_health():
    assert client.get("/healthz").json() == {"status": "ok"}

def test_greeting():
    response = client.post("/greet", json={"name": "Alex"})
    assert response.status_code == 200
    assert response.json() == {"message": "Hello, Alex!"}

def test_invalid_name():
    for name in ("", "  ", "x" * 81):
        assert client.post("/greet", json={"name": name}).status_code == 422

pid /tmp/nginx.pid;
error_log /dev/stderr warn;
events { worker_connections 512; }
http {
  include /etc/nginx/mime.types;
  default_type application/octet-stream;
  access_log /dev/stdout;
  sendfile on;
  server_tokens off;
  client_body_temp_path /tmp/client_body;
  proxy_temp_path /tmp/proxy;
  fastcgi_temp_path /tmp/fastcgi;
  uwsgi_temp_path /tmp/uwsgi;
  scgi_temp_path /tmp/scgi;
  server {
    listen 3000;
    root /usr/share/nginx/html;
    index index.html;
    location = /healthz { access_log off; default_type text/plain; return 200 "ok\n"; }
    location / { try_files $uri $uri.html $uri/ =404; }
  }
}
